WITH
retailer_map AS (SELECT * FROM UNNEST([STRUCT('Spain' AS CNTRY,'ELCORTEINGLES_ELECTRONICA' AS RTLR_NAME),STRUCT('Spain','MEDIAMARKT'),STRUCT('France','DARTY'),STRUCT('France','BOULANGER'),STRUCT('Italy','MEDIAWORLD'),STRUCT('Italy','AMAZON'),STRUCT('Italy','UNIEURO'),STRUCT('Netherlands','COOLBLUE'),STRUCT('Sweden','ELGIGANTEN'),STRUCT('Germany','AMAZON'),STRUCT('Germany','MEDIAMARKT'),STRUCT('Germany','OTTO'),STRUCT('UK','AO'),STRUCT('UK','CURRYS'),STRUCT('Canada','COSTCO'),STRUCT('Chile','FALABELLA'),STRUCT('Mexico','LIVERPOOL'),STRUCT('Brazil','MAGAZINELUIZA'),STRUCT('SaudiArabia','EXTRA'),STRUCT('Singapore','LAZADA'),STRUCT('Thailand','LAZADA'),STRUCT('Taiwan','MOMOSHOP'),STRUCT('Vietnam','DIENMAYXANH')])),
brand_map AS (SELECT * FROM UNNEST([STRUCT('Spain' AS CNTRY,'ELCORTEINGLES_ELECTRONICA' AS RTLR_NAME,'W/M' AS DIV,['LG','BOSCH','SAMSUNG','HISENSE'] AS BRANDS),STRUCT('Spain','ELCORTEINGLES_ELECTRONICA','REF',['LG','SAMSUNG','HISENSE','BOSCH']),STRUCT('Spain','ELCORTEINGLES_ELECTRONICA','D/W',['LG','BOSCH','BALAY','BEKO','HISENSE']),STRUCT('Spain','ELCORTEINGLES_ELECTRONICA','DRY',['LG','BOSCH','SAMSUNG','HISENSE']),STRUCT('Spain','MEDIAMARKT','W/M',['LG','BOSCH','SAMSUNG','HISENSE']),STRUCT('Spain','MEDIAMARKT','REF',['LG','SAMSUNG','HISENSE','BOSCH']),STRUCT('Spain','MEDIAMARKT','D/W',['LG','BOSCH','BALAY','BEKO','HISENSE']),STRUCT('Spain','MEDIAMARKT','DRY',['LG','BOSCH','SAMSUNG','HISENSE']),STRUCT('France','DARTY','W/M',['BOSCH','SAMSUNG','LG','HISENSE']),STRUCT('France','DARTY','REF',['SAMSUNG','HISENSE','LG','HAIER']),STRUCT('France','DARTY','DRY',['BOSCH','SAMSUNG','LG','HISENSE']),STRUCT('France','BOULANGER','W/M',['BOSCH','SAMSUNG','LG','HISENSE']),STRUCT('France','BOULANGER','REF',['SAMSUNG','HISENSE','LG','HAIER']),STRUCT('France','BOULANGER','DRY',['BOSCH','SAMSUNG','LG','HISENSE']),STRUCT('Italy','MEDIAWORLD','W/M',['LG','SAMSUNG','BOSCH','HISENSE','CANDY']),STRUCT('Italy','MEDIAWORLD','REF',['SAMSUNG','HISENSE','LG','BOSCH','HAIER']),STRUCT('Italy','MEDIAWORLD','DRY',['LG','SAMSUNG','BOSCH','HISENSE','CANDY']),STRUCT('Italy','AMAZON','W/M',['LG','SAMSUNG','BOSCH','HISENSE','CANDY']),STRUCT('Italy','AMAZON','REF',['SAMSUNG','HISENSE','LG','BOSCH','HAIER']),STRUCT('Italy','AMAZON','DRY',['LG','SAMSUNG','BOSCH','HISENSE','CANDY']),STRUCT('Italy','UNIEURO','W/M',['LG','SAMSUNG','BOSCH','HISENSE','CANDY']),STRUCT('Italy','UNIEURO','REF',['SAMSUNG','HISENSE','LG','BOSCH','HAIER']),STRUCT('Italy','UNIEURO','DRY',['LG','SAMSUNG','BOSCH','HISENSE','CANDY']),STRUCT('Netherlands','COOLBLUE','W/M',['SAMSUNG','BOSCH','AEG','LG']),STRUCT('Netherlands','COOLBLUE','REF',['SAMSUNG','BOSCH','ETNA','LG']),STRUCT('Netherlands','COOLBLUE','DRY',['SAMSUNG','BOSCH','AEG','LG']),STRUCT('Sweden','ELGIGANTEN','W/M',['BOSCH','ELECTROLUX','LG','SAMSUNG','HISENSE']),STRUCT('Sweden','ELGIGANTEN','REF',['SAMSUNG','ELECTROLUX','LG','BOSCH','HISENSE']),STRUCT('Sweden','ELGIGANTEN','DRY',['BOSCH','ELECTROLUX','LG','SAMSUNG','HISENSE']),STRUCT('Germany','AMAZON','REF',['LG','EXQUISIT','BOSCH','KLARSTEIN','BOMANN','SIEMENS','LIEBHERR','SAMSUNG']),STRUCT('Germany','AMAZON','W/M',['LG','BOSCH','AEG','CECOTEC','SIEMENS','SAMSUNG']),STRUCT('Germany','AMAZON','DRY',['LG','SAMSUNG','BOSCH','SIEMENS']),STRUCT('Germany','MEDIAMARKT','REF',['LG','SAMSUNG','BOSCH','EXQUISIT','LIEBHERR','BOMANN']),STRUCT('Germany','MEDIAMARKT','W/M',['LG','SAMSUNG','BAUKNECHT','SIEMENS','BOSCH','AEG']),STRUCT('Germany','MEDIAMARKT','DRY',['LG','SAMSUNG','BOSCH','SIEMENS']),STRUCT('Germany','OTTO','REF',['LG','EXQUISIT','LIEBHERR','SIEMENS','BOSCH','AMICA','SAMSUNG']),STRUCT('Germany','OTTO','W/M',['LG','BOSCH','AEG','BAUKNECHT','SIEMENS','BEKO','SAMSUNG']),STRUCT('Germany','OTTO','DRY',['LG','SAMSUNG','BOSCH','SIEMENS']),STRUCT('UK','AO','REF',['LG','SMEG','HISENSE','BEKO','SAMSUNG','RUSSELLHOBBS','BOSCH']),STRUCT('UK','AO','W/M',['LG','HOOVER','HOTPOINT','BEKO','AEG','HAIER','BOSCH','HISENSE','SAMSUNG']),STRUCT('UK','AO','DRY',['LG','SAMSUNG','BOSCH','HISENSE']),STRUCT('UK','AO','D/W',['LG','BOSCH','HISENSE']),STRUCT('UK','CURRYS','REF',['LG','HISENSE','BEKO','SAMSUNG','HAIER','BOSCH']),STRUCT('UK','CURRYS','W/M',['LG','HOOVER','HOTPOINT','BEKO','SAMSUNG','HAIER','BOSCH','HISENSE']),STRUCT('UK','CURRYS','DRY',['LG','SAMSUNG','BOSCH','HISENSE']),STRUCT('UK','CURRYS','D/W',['LG','BOSCH','HISENSE']),STRUCT('Canada','COSTCO','W/M',['LG','SAMSUNG','GE','WHIRLPOOL','MIDEA']),STRUCT('Canada','COSTCO','REF',['LG','SAMSUNG','FRIGIDAIRE','WHIRLPOOL','HISENSE']),STRUCT('Canada','COSTCO','DRY',['LG','SAMSUNG','GE','WHIRLPOOL','MIDEA']),STRUCT('Chile','FALABELLA','W/M',['LG','SAMSUNG','MIDEA','MADEMSA']),STRUCT('Chile','FALABELLA','REF',['LG','SAMSUNG','MIDEA','MADEMSA']),STRUCT('Chile','FALABELLA','DRY',['LG','SAMSUNG','MIDEA','MADEMSA']),STRUCT('Mexico','LIVERPOOL','W/M',['LG','SAMSUNG','MABE','WHIRLPOOL']),STRUCT('Mexico','LIVERPOOL','REF',['LG','SAMSUNG','MABE','HISENSE']),STRUCT('Mexico','LIVERPOOL','DRY',['LG','SAMSUNG','MABE','WHIRLPOOL']),STRUCT('Brazil','MAGAZINELUIZA','W/M',['LG','SAMSUNG','ELECTROLUX','BRASTEMP','MIDEA']),STRUCT('Brazil','MAGAZINELUIZA','REF',['LG','SAMSUNG','ELECTROLUX','BRASTEMP','MIDEA']),STRUCT('Brazil','MAGAZINELUIZA','DRY',['LG','SAMSUNG','ELECTROLUX','BRASTEMP','MIDEA']),STRUCT('SaudiArabia','EXTRA','W/M',['LG','SAMSUNG','MIDEA','TOSHIBA']),STRUCT('SaudiArabia','EXTRA','REF',['LG','SAMSUNG','HITACHI','TOSHIBA']),STRUCT('SaudiArabia','EXTRA','DRY',['LG','SAMSUNG','MIDEA','TOSHIBA']),STRUCT('Singapore','LAZADA','W/M',['LG','SAMSUNG','TOSHIBA','MIDEA']),STRUCT('Singapore','LAZADA','REF',['LG','SAMSUNG','HITACHI','PANASONIC']),STRUCT('Singapore','LAZADA','DRY',['LG','SAMSUNG','TOSHIBA','MIDEA']),STRUCT('Thailand','LAZADA','W/M',['LG','SAMSUNG','TOSHIBA','HISENSE']),STRUCT('Thailand','LAZADA','REF',['LG','SAMSUNG','TOSHIBA','HISENSE']),STRUCT('Thailand','LAZADA','DRY',['LG','SAMSUNG','TOSHIBA','HISENSE']),STRUCT('Taiwan','MOMOSHOP','W/M',['LG','PANASONIC','SANLUX','WHIRLPOOL']),STRUCT('Taiwan','MOMOSHOP','REF',['LG','PANASONIC','HITACHI','SANLUX']),STRUCT('Taiwan','MOMOSHOP','DRY',['LG','PANASONIC','SANLUX','WHIRLPOOL']),STRUCT('Vietnam','DIENMAYXANH','W/M',['LG','SAMSUNG','ELECTROLUX','TOSHIBA','AQUA']),STRUCT('Vietnam','DIENMAYXANH','REF',['LG','SAMSUNG','TOSHIBA','AQUA']),STRUCT('Vietnam','DIENMAYXANH','DRY',['LG','SAMSUNG','ELECTROLUX','TOSHIBA','AQUA'])])),
country_map AS (SELECT * FROM UNNEST([STRUCT('Spain' AS CNTRY,'ES' AS CODE),STRUCT('France','FR'),STRUCT('Italy','IT'),STRUCT('Netherlands','NL'),STRUCT('Sweden','SE'),STRUCT('Germany','DE'),STRUCT('UK','UK'),STRUCT('UK','GB'),STRUCT('Canada','CA'),STRUCT('Chile','CL'),STRUCT('Mexico','MX'),STRUCT('Brazil','BR'),STRUCT('SaudiArabia','SA'),STRUCT('Singapore','SG'),STRUCT('Thailand','TH'),STRUCT('Taiwan','TW'),STRUCT('Vietnam','VN')])),
source_rows AS (
 SELECT DATE AS RPT_DATE,TRIM(CNTRY) CNTRY,TRIM(ONLINE_STR) RTLR_NAME,TRIM(BRAND) BRAND,
 CAT,RPC,MPC,TRIM(URL) RAW_URL,PRODUCT_DESC,AVLBL_STAT,RK,
 OBSRV_LIST_PRICE,OBSRV_DC_PRICE,CURRENCY_CODE,IMG_COUNT,VIDEO_COUNT,SALE_AMT,SALE_QTY,SEARCH_TERM,
 CAST(NULL AS STRING) PRODUCT_IMG_URL,CAST(NULL AS FLOAT64) PRICE,CAST(NULL AS FLOAT64) DC_PRICE,CAST(NULL AS STRING) CURRENCY,
 'SALE_RK' SOURCE_TYPE,1 SOURCE_PRIORITY
 FROM `pjt-lge-oned.L2_ONED.VSMRKT_DAILY_OSM_SALE_RK_D` WHERE DATE BETWEEN DATE_SUB(DATE '2026-11-17',INTERVAL 29 DAY) AND DATE '2026-11-17'
 UNION ALL
 SELECT DATE,TRIM(CNTRY),TRIM(ONLINE_STR),TRIM(BRAND),CAT,RPC,MPC,TRIM(URL),PRODUCT_DESC,CAST(NULL AS STRING),RK,
 NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,PRODUCT_IMG_URL,PRICE,DC_PRICE,CURRENCY,'BANR_VSBLT',2
 FROM `pjt-lge-oned.L2_ONED.VSMRKT_DAILY_OSM_BANR_VSBLT_D` WHERE DATE BETWEEN DATE_SUB(DATE '2026-11-17',INTERVAL 29 DAY) AND DATE '2026-11-17'
), normalized AS (
 SELECT *,CASE WHEN UPPER(CNTRY)='SPAIN' AND UPPER(RTLR_NAME)='ELCORTEINGLES_ELECTRONICA' THEN REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(RAW_URL,r'([?&])(?:stype|parentCategoryId|color|pdp_ctype|analytics_data)=[^&#]*',r'\1'),r'([?&])&+',r'\1'),r'[?&]+(#|$)',r'\1') ELSE RAW_URL END CAT_URL_ADDR,
 CASE UPPER(TRIM(CAT)) WHEN 'WASHING MACHINE_HA' THEN 'W/M' WHEN 'REFRIGERATOR_HA' THEN 'REF'
 WHEN 'DISHWASHER_HA' THEN 'D/W' WHEN 'DRYER_HA' THEN 'DRY' END DIV,
 COALESCE(NULLIF(UPPER(TRIM(MPC)),''),NULLIF(UPPER(TRIM(RPC)),'')) MODEL_DEDUP_KEY,
 CASE WHEN UPPER(TRIM(BRAND)) ='LG ELECTRONICS' THEN 'LG' WHEN UPPER(RTLR_NAME) IN ('MOMOSHOP') AND REGEXP_CONTAINS(UPPER(TRIM(BRAND)),r'^【?\s*([A-Z]+)') THEN REGEXP_REPLACE(UPPER(TRIM(BRAND)),r'^【?\s*([A-Z]+).*$',r'\1') ELSE REGEXP_REPLACE(UPPER(TRIM(BRAND)),r'\s+','') END BRAND_KEY
 FROM source_rows
), history_candidates AS (
 SELECT n.* FROM normalized n
 WHERE LENGTH(IFNULL(CAT_URL_ADDR,''))>0
 AND EXISTS(SELECT 1 FROM retailer_map r WHERE UPPER(n.CNTRY)=UPPER(r.CNTRY) AND UPPER(n.RTLR_NAME)=UPPER(r.RTLR_NAME))
 AND EXISTS(SELECT 1 FROM brand_map b WHERE UPPER(n.CNTRY)=UPPER(b.CNTRY) AND (b.RTLR_NAME='*' OR UPPER(n.RTLR_NAME)=UPPER(b.RTLR_NAME))
 AND n.DIV=b.DIV AND n.BRAND_KEY IN UNNEST(b.BRANDS))
), daily_counts AS (
 SELECT RPT_DATE,CNTRY,RTLR_NAME,DIV,COUNT(DISTINCT CAT_URL_ADDR) URL_COUNT
 FROM history_candidates GROUP BY 1,2,3,4
), ranked_counts AS (
 SELECT *,ROW_NUMBER() OVER(PARTITION BY CNTRY,RTLR_NAME,DIV ORDER BY URL_COUNT,RPT_DATE) N,
 COUNT(*) OVER(PARTITION BY CNTRY,RTLR_NAME,DIV) OBSERVED_DAYS FROM daily_counts
), baselines AS (
 SELECT CNTRY,RTLR_NAME,DIV,URL_COUNT BASELINE_URLS,OBSERVED_DAYS
 FROM ranked_counts WHERE N=CAST(FLOOR((OBSERVED_DAYS-1)*0.75)+1 AS INT64)
), required_groups AS (
 SELECT CNTRY,RTLR_NAME,COUNT(DISTINCT DIV) GROUP_COUNT FROM brand_map WHERE CONCAT(CNTRY,'|',RTLR_NAME,'|',DIV) NOT IN ('Canada|COSTCO|DRY','Chile|FALABELLA|DRY','Mexico|LIVERPOOL|DRY','Brazil|MAGAZINELUIZA|DRY','SaudiArabia|EXTRA|DRY','Singapore|LAZADA|DRY','Thailand|LAZADA|DRY','Taiwan|MOMOSHOP|DRY','Vietnam|DIENMAYXANH|DRY') GROUP BY 1,2
), eligible_dates AS (
 SELECT d.CNTRY,d.RTLR_NAME,d.RPT_DATE
 FROM daily_counts d JOIN baselines b ON d.CNTRY=b.CNTRY AND d.RTLR_NAME=b.RTLR_NAME AND d.DIV=b.DIV
 JOIN required_groups g ON g.CNTRY=d.CNTRY AND g.RTLR_NAME=d.RTLR_NAME
 WHERE b.OBSERVED_DAYS>=3 AND d.URL_COUNT>=b.BASELINE_URLS*0.8 AND CONCAT(d.CNTRY,'|',d.RTLR_NAME,'|',d.DIV) NOT IN ('Canada|COSTCO|DRY','Chile|FALABELLA|DRY','Mexico|LIVERPOOL|DRY','Brazil|MAGAZINELUIZA|DRY','SaudiArabia|EXTRA|DRY','Singapore|LAZADA|DRY','Thailand|LAZADA|DRY','Taiwan|MOMOSHOP|DRY','Vietnam|DIENMAYXANH|DRY')
 GROUP BY 1,2,3
 HAVING COUNT(DISTINCT d.DIV)=MAX(g.GROUP_COUNT)
), chosen_dates AS (
 SELECT r.CNTRY,r.RTLR_NAME,CASE WHEN CONCAT(r.CNTRY,'|',r.RTLR_NAME)='Canada|COSTCO' THEN DATE '2026-11-15' ELSE MAX(e.RPT_DATE) END SELECTED_DATE
 FROM retailer_map r LEFT JOIN eligible_dates e ON r.CNTRY=e.CNTRY AND r.RTLR_NAME=e.RTLR_NAME GROUP BY 1,2
), date_lags AS (
 SELECT *,CAST(EXTRACT(DAY FROM (CAST(DATE '2026-11-17' AS TIMESTAMP)-CAST(SELECTED_DATE AS TIMESTAMP)))
 +EXTRACT(HOUR FROM (CAST(DATE '2026-11-17' AS TIMESTAMP)-CAST(SELECTED_DATE AS TIMESTAMP)))/24 AS INT64) DATE_LAG_DAYS FROM chosen_dates
), date_decisions AS (
 SELECT *,DATE '2026-11-17' REQUESTED_DATE,
 CASE WHEN CONCAT(CNTRY,'|',RTLR_NAME)='Canada|COSTCO' THEN '사람 지정 기준일 · 11-16은 배너 노출 표가 비어 건조기 0행(사용자 결정 11-18)' WHEN SELECTED_DATE IS NULL THEN '확인 필요 · 수집량 부족 또는 관측일 3일 미만'
 WHEN DATE_LAG_DAYS>15 THEN '확인 필요 · 15일 초과 과거 데이터'
 WHEN SELECTED_DATE=DATE '2026-11-17' THEN '기준일 사용' ELSE '최근 충분한 수집일 사용' END DATE_SELECTION_REASON
 FROM date_lags
), candidates AS (
 SELECT h.*,d.REQUESTED_DATE,d.DATE_LAG_DAYS,d.DATE_SELECTION_REASON FROM history_candidates h
 JOIN date_decisions d ON h.CNTRY=d.CNTRY AND h.RTLR_NAME=d.RTLR_NAME AND h.RPT_DATE=d.SELECTED_DATE
), detail_normalized AS (
 SELECT t.BASE_DATE DETAIL_DATE,c.CNTRY,UPPER(TRIM(t.SITE_NAME)) RTLR_NAME,CASE WHEN UPPER(c.CNTRY)='SPAIN' AND UPPER(TRIM(t.SITE_NAME))='ELCORTEINGLES_ELECTRONICA' THEN REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(TRIM(t.PRODUCT_PAGE_URL_ADDR),r'([?&])(?:stype|parentCategoryId|color|pdp_ctype|analytics_data)=[^&#]*',r'\1'),r'([?&])&+',r'\1'),r'[?&]+(#|$)',r'\1') ELSE TRIM(t.PRODUCT_PAGE_URL_ADDR) END CAT_URL_ADDR,
 NULLIF(TRIM(t.SLLR_NAME),'') SLLR_NAME,
 NULLIF(REGEXP_REPLACE(UPPER(TRIM(t.SLLR_NAME)),r'[\s._-]+',''),'') SELLER_KEY,
 NULLIF(REGEXP_REPLACE(UPPER(TRIM(t.INV_STAT_INFO)),r'[\s_-]+',' '),'') INV_STAT_INFO,
 NULLIF(TRIM(t.SITE_PRODUCT_NAME),'') SITE_PRODUCT_NAME
 FROM `pjt-lge-oned.L1_ONED.TRPURC_OSM_PRODUCT_DAILY_L` t
 JOIN country_map c ON UPPER(TRIM(t.CNTRY_CODE))=c.CODE
 JOIN chosen_dates x ON x.CNTRY=c.CNTRY AND UPPER(x.RTLR_NAME)=UPPER(TRIM(t.SITE_NAME)) AND x.SELECTED_DATE=t.BASE_DATE
 WHERE t.BASE_DATE BETWEEN DATE_SUB(DATE '2026-11-17',INTERVAL 29 DAY) AND DATE '2026-11-17'
 AND EXISTS(SELECT 1 FROM retailer_map r WHERE r.CNTRY=c.CNTRY AND UPPER(r.RTLR_NAME)=UPPER(TRIM(t.SITE_NAME)))
), detail AS (
 SELECT DETAIL_DATE,CNTRY,RTLR_NAME,CAT_URL_ADDR,COUNT(*) DETAIL_MATCH_COUNT,
 COUNT(DISTINCT SELLER_KEY) SELLER_VALUE_COUNT,SUM(IF(SELLER_KEY IS NULL,1,0)) SELLER_EMPTY_COUNT,
 COUNT(DISTINCT INV_STAT_INFO) STOCK_VALUE_COUNT,
 COUNT(DISTINCT SITE_PRODUCT_NAME) TITLE_VALUE_COUNT,
 IF(COUNT(DISTINCT SELLER_KEY)=1,MIN(SELLER_KEY),NULL) SELLER_KEY,
 IF(COUNT(DISTINCT SELLER_KEY)=1,MIN(SLLR_NAME),NULL) SLLR_NAME,
 IF(COUNT(DISTINCT INV_STAT_INFO)=1,MIN(INV_STAT_INFO),NULL) INV_STAT_INFO,
 IF(COUNT(DISTINCT SITE_PRODUCT_NAME)=1,MIN(SITE_PRODUCT_NAME),NULL) SITE_PRODUCT_NAME
 FROM detail_normalized GROUP BY 1,2,3,4
), enriched AS (
 SELECT u.*,IFNULL(d.DETAIL_MATCH_COUNT,0) DETAIL_MATCH_COUNT,IFNULL(d.SELLER_VALUE_COUNT,0) SELLER_VALUE_COUNT,
 IFNULL(d.SELLER_EMPTY_COUNT,0) SELLER_EMPTY_COUNT,
 IFNULL(d.STOCK_VALUE_COUNT,0) STOCK_VALUE_COUNT,IFNULL(d.TITLE_VALUE_COUNT,0) TITLE_VALUE_COUNT,
 d.SLLR_NAME,d.SELLER_KEY,d.INV_STAT_INFO,d.SITE_PRODUCT_NAME,
 LOWER(COALESCE(d.SITE_PRODUCT_NAME,NULLIF(TRIM(u.PRODUCT_DESC),''),'')) JUDGE_NAME,
 REGEXP_REPLACE(UPPER(TRIM(IFNULL(u.AVLBL_STAT,''))),r'[\s_-]+',' ') SALE_STATUS
 FROM candidates u LEFT JOIN detail d ON u.RPT_DATE=d.DETAIL_DATE AND u.CNTRY=d.CNTRY AND UPPER(u.RTLR_NAME)=d.RTLR_NAME AND u.CAT_URL_ADDR=d.CAT_URL_ADDR
), seller AS (
 SELECT *,REGEXP_CONTAINS(SALE_STATUS,r'MARKET\s*PLACE') STATUS_MARKETPLACE,
 (SELLER_VALUE_COUNT=1 AND SELLER_EMPTY_COUNT=0) ONE_SELLER,
 (SELLER_KEY=REGEXP_REPLACE(UPPER(RTLR_NAME),r'[\s._-]+','')) SELLER_IS_RETAILER
 FROM enriched
), flags AS (
 SELECT *,
 MODEL_DEDUP_KEY IS NULL MISSING_MODEL,
 (STOCK_VALUE_COUNT<=1 AND NOT (IFNULL(INV_STAT_INFO,'') IN ('IN STOCK','OUT OF STOCK','NOT FOUND') AND SALE_STATUS IN ('IN STOCK','OUT OF STOCK','NOT FOUND') AND IFNULL(INV_STAT_INFO,'')<>SALE_STATUS) AND (IFNULL(INV_STAT_INFO,'')='NOT FOUND' OR SALE_STATUS='NOT FOUND')) PAGE_NOT_FOUND,
 (STOCK_VALUE_COUNT<=1 AND NOT (IFNULL(INV_STAT_INFO,'') IN ('IN STOCK','OUT OF STOCK','NOT FOUND') AND SALE_STATUS IN ('IN STOCK','OUT OF STOCK','NOT FOUND') AND IFNULL(INV_STAT_INFO,'')<>SALE_STATUS) AND (IFNULL(INV_STAT_INFO,'')='OUT OF STOCK' OR SALE_STATUS='OUT OF STOCK')) OUT_OF_STOCK,
 (STATUS_MARKETPLACE OR (ONE_SELLER AND NOT SELLER_IS_RETAILER)) MARKETPLACE,
 (TITLE_VALUE_COUNT<=1 AND REGEXP_CONTAINS(JUDGE_NAME,r'refurb|renewed|reconditioned|recertified|second[\s_-]*hand|(^|[^a-z])used([^a-z]|$)|open[\s_-]*box|reconditionn|reacondicionad|ricondizionat|seminuevo|generalüberholt|2nd[\s_-]*life')
) USED_PRODUCT,
 (TITLE_VALUE_COUNT<=1 AND REGEXP_CONTAINS(JUDGE_NAME,r'(^|[^a-z])accessor(y|ies)([^a-z]|$)')) ACCESSORY,
 (TITLE_VALUE_COUNT<=1 AND REGEXP_CONTAINS(JUDGE_NAME,r'(^|[^a-z])outlet([^a-z]|$)') OR REGEXP_CONTAINS(LOWER(CAT_URL_ADDR),r'/outlet(/|$)')) OUTLET,
 (NOT STATUS_MARKETPLACE AND (SELLER_VALUE_COUNT>1 OR (SELLER_VALUE_COUNT=1 AND SELLER_EMPTY_COUNT>0))) SELLER_UNKNOWN,
 (STOCK_VALUE_COUNT>1 OR (IFNULL(INV_STAT_INFO,'') IN ('IN STOCK','OUT OF STOCK','NOT FOUND') AND SALE_STATUS IN ('IN STOCK','OUT OF STOCK','NOT FOUND') AND IFNULL(INV_STAT_INFO,'')<>SALE_STATUS) OR (IFNULL(INV_STAT_INFO,'') NOT IN ('IN STOCK','OUT OF STOCK','NOT FOUND') AND SALE_STATUS NOT IN ('IN STOCK','OUT OF STOCK','NOT FOUND'))) STOCK_UNKNOWN,
 (JUDGE_NAME='' OR TITLE_VALUE_COUNT>1) TITLE_UNKNOWN
 FROM seller
), filtered AS (
 SELECT *,CASE WHEN FALSE AND MISSING_MODEL THEN '02 모델코드 없음'
 WHEN FALSE AND PAGE_NOT_FOUND THEN '03 페이지 없음'
 WHEN FALSE AND MARKETPLACE THEN '04 외부 판매자'
 WHEN FALSE AND OUT_OF_STOCK THEN '05 품절'
 WHEN FALSE AND USED_PRODUCT THEN '06 중고·리퍼'
 WHEN FALSE AND ACCESSORY THEN '07 액세서리'
 WHEN FALSE AND OUTLET THEN '08 아울렛' ELSE '' END FILTER_REASON
 FROM flags
), url_ranked AS (
 SELECT *,ROW_NUMBER() OVER(PARTITION BY CNTRY,RTLR_NAME,CAT_URL_ADDR
 ORDER BY IF(FILTER_REASON='',0,1),IF(MODEL_DEDUP_KEY IS NULL,1,0),SOURCE_PRIORITY,RK,RAW_URL,IFNULL(MPC,''),IFNULL(RPC,''),IFNULL(PRODUCT_DESC,''),IFNULL(AVLBL_STAT,'')) URL_RANK
 FROM filtered
), classified AS (
 SELECT * EXCEPT(FILTER_REASON),IF(URL_RANK>1,'01 동일 URL 중복',FILTER_REASON) EXCLUSION_REASON,
 CONCAT(IF(DETAIL_MATCH_COUNT=0,'상품상세 미연결; ',''),IF(SELLER_UNKNOWN,'판매자 판정 불가; ',''),
 IF(STOCK_UNKNOWN,'재고 판정 불가; ',''),IF(TITLE_UNKNOWN,'상품명 판정 불가; ',''),
 IF(SELLER_VALUE_COUNT>1 OR STOCK_VALUE_COUNT>1 OR TITLE_VALUE_COUNT>1 OR (SELLER_VALUE_COUNT=1 AND SELLER_EMPTY_COUNT>0),'상품상세 값 충돌; ','')) UNKNOWN_REASONS,
 (FALSE AND SELLER_UNKNOWN) OR ((FALSE OR FALSE) AND STOCK_UNKNOWN)
 OR ((FALSE OR FALSE OR FALSE) AND TITLE_UNKNOWN) AS JUDGMENT_UNKNOWN
 FROM url_ranked
), model_ranked AS (
 SELECT *,ROW_NUMBER() OVER(PARTITION BY CNTRY,RTLR_NAME,DIV,BRAND_KEY,MODEL_DEDUP_KEY,EXCLUSION_REASON
 ORDER BY SOURCE_PRIORITY,RK,CAT_URL_ADDR,RAW_URL) MODEL_RANK FROM classified
), audited AS (
 SELECT * EXCEPT(EXCLUSION_REASON),CASE WHEN EXCLUSION_REASON<>'' THEN EXCLUSION_REASON WHEN FALSE AND MODEL_DEDUP_KEY IS NOT NULL AND MODEL_RANK>1 THEN '09 동일 모델 중복' ELSE '' END EXCLUSION_REASON
 FROM model_ranked
 )
SELECT REQUESTED_DATE,RPT_DATE,DATE_LAG_DAYS,DATE_SELECTION_REASON,CNTRY,RTLR_NAME,BRAND,DIV,RPC,MPC,CAT_URL_ADDR,RAW_URL,MODEL_DEDUP_KEY,PRODUCT_DESC,
AVLBL_STAT,OBSRV_LIST_PRICE,OBSRV_DC_PRICE,CURRENCY_CODE,RK,CAT,IMG_COUNT,VIDEO_COUNT,SALE_AMT,SALE_QTY,SEARCH_TERM,
PRODUCT_IMG_URL,PRICE,DC_PRICE,CURRENCY,SOURCE_TYPE,SLLR_NAME,INV_STAT_INFO,SITE_PRODUCT_NAME,DETAIL_MATCH_COUNT,
IF(EXCLUSION_REASON<>'','제외',IF(JUDGMENT_UNKNOWN,'포함 · 판정 불가 있음','포함')) AS RESULT_STATUS,
EXCLUSION_REASON,UNKNOWN_REASONS,JUDGMENT_UNKNOWN,MISSING_MODEL,PAGE_NOT_FOUND,MARKETPLACE,OUT_OF_STOCK,
USED_PRODUCT,ACCESSORY,OUTLET,SELLER_UNKNOWN,STOCK_UNKNOWN,TITLE_UNKNOWN FROM audited ORDER BY CNTRY,RTLR_NAME,DIV,RK,CAT_URL_ADDR,SOURCE_TYPE
